import React, { useState, useEffect } from 'react';
// import './App.css'; // Artık buna ihtiyacımız yok, sildik!

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]); 
  const [filtre, setFiltre] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(Array.isArray(data) ? data : []))
      .catch(err => console.error("Bağlantı Hatası:", err));
  }, []);

  const favoriEkleCikar = (mekan) => {
    setFavoriler((prev) => {
      const aktifListe = Array.isArray(prev) ? prev : [];
      const varMi = aktifListe.some(f => f.id === mekan.id);
      return varMi 
        ? aktifListe.filter(f => f.id !== mekan.id)
        : [...aktifListe, { ...mekan, sure: Number(mekan.sure) || 0 }];
    });
  };

  const toplamSure = (favoriler || []).reduce((toplam, m) => toplam + (Number(m.sure) || 0), 0);

  const filtrelenmis = mekanlar.filter(m => {
    const katUygun = filtre === 'Hepsi' || m.kategori === filtre;
    const sureUygun = maxSure === '' || (Number(m.sure) || 0) <= Number(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="container">
      {/* --- İŞTE SİHİRLİ DOKUNUŞ BURADA --- */}
      {/* CSS kodlarını doğrudan sayfanın içine enjekte ediyoruz */}
      <style>{`
        body { font-family: 'Poppins', sans-serif; background-color: #f4f7f9; margin: 0; padding: 20px; }
        .header { text-align: center; margin-bottom: 30px; color: #1a4d6e; }
        .controls { display: flex; justify-content: center; gap: 10px; margin-bottom: 25px; flex-wrap: wrap; }
        .summary-bar { background: #1a4d6e; color: white; padding: 15px; border-radius: 50px; display: flex; justify-content: space-around; margin-bottom: 40px; font-weight: bold; }
        .grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 25px; }

        /* --- KART TASARIMI --- */
        .card {
          width: 280px;
          background: white;
          border-radius: 20px;
          overflow: hidden;
          box-shadow: 0 5px 15px rgba(0,0,0,0.08);
          cursor: pointer;
          display: flex;
          flex-direction: column;
          /* Geçiş efekti */
          transition: all 0.3s ease-in-out;
          /* Zıplamayı önleyen şeffaf kenarlık */
          border: 3px solid transparent; 
          box-sizing: border-box;
        }

        /* --- HOVER (ÜZERİNE GELİNCE) --- */
        .card:hover {
          transform: scale(0.95) !important; /* Küçülür */
          border: 3px solid #00c2cb !important; /* Turkuaz Kenarlık */
          box-shadow: 0 2px 8px rgba(0,0,0,0.15) !important;
        }

        .card-image-container { height: 180px; position: relative; padding: 10px; }
        .card-img { width: 100%; height: 100%; object-fit: cover; border-radius: 15px; }
        .badge { position: absolute; top: 15px; right: 15px; color: white; padding: 5px 10px; border-radius: 10px; font-size: 12px; }
        .card-content { padding: 15px; flex-grow: 1; }
        .btn-action { width: 100%; padding: 8px; border: none; border-radius: 10px; margin-top: 10px; cursor: pointer; font-weight: bold; }
        .btn-add { background: #eafaf1; color: #00c2cb; border: 1px solid #00c2cb; }
        .btn-remove { background: #fdedec; color: #ef4444; border: 1px solid #ef4444; }
      `}</style>
      {/* ----------------------------------- */}

      <div className="header">
        <h1>🌴 Antalya Rota Asistanı</h1>
      </div>

      <div className="controls">
        <input type="number" className="search-input" placeholder="Maks. Süre (dk)" 
          value={maxSure} onChange={(e) => setMaxSure(e.target.value)} 
          style={{padding: '10px', borderRadius: '20px', border: '1px solid #ccc'}} />
        {['Hepsi', 'Tarih', 'Doğa', 'Yemek', 'Eğlence'].map(k => (
          <button key={k} className={`filter-btn ${filtre === k ? 'active' : ''}`} 
            onClick={() => setFiltre(k)}
            style={{padding: '8px 15px', borderRadius: '20px', border: 'none', cursor: 'pointer', background: filtre === k ? '#1a4d6e' : 'white', color: filtre === k ? 'white' : 'black'}}
          >
            {k}
          </button>
        ))}
      </div>

      <div className="summary-bar">
        <span>Seçilen: {favoriler.length} Mekan</span>
        <span>Toplam: {Math.floor(toplamSure / 60)}sa {toplamSure % 60}dk</span>
      </div>

      <div className="grid">
        {filtrelenmis.map(m => {
          const seciliMi = favoriler?.some(f => f.id === m.id);
          return (
            <div key={m.id} className="card" onClick={() => favoriEkleCikar(m)}>
              <div className="card-image-container">
                <img src={m.resim} alt={m.ad} className="card-img" />
                <span className="badge" style={{ backgroundColor: '#2c3e50' }}>{m.kategori}</span>
              </div>
              <div className="card-content">
                <h3 style={{margin: '0 0 10px 0', color: '#1a4d6e'}}>{m.ad}</h3>
                <div style={{fontSize: '13px', color: '#666', display: 'flex', justifyContent: 'space-between'}}>
                   <span>📍 {m.bolge}</span>
                   <span>⏳ {m.sure} dk</span>
                </div>
                <button className={`btn-action ${seciliMi ? 'btn-remove' : 'btn-add'}`}>
                  {seciliMi ? 'Çıkar' : 'Ekle'}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default App;
